        internal static BossMoveProfile[] CreateErebosMoves() => new[]
        {
            ErebosProfile("weapon", "通常攻撃が命中したとき、命中した敵の方向へ長さ6m・幅0.6mの直線を0.3秒間予告し、0.3秒間隔で2回、光属性ダメージを与える。ダメージは各攻撃力・魔力の高い方の8%で、同じ敵には最大2回まで命中する。再発動まで5秒かかる。", "When your basic attack hits, show a warning for 0.3 seconds along a line toward the enemy, 6m long and 0.6m wide. Then deal Light damage twice, 0.3 seconds apart, each equal to 8% of whichever is higher: your Attack or Ability Power. Each enemy can be hit up to twice. Cooldown: 5 seconds.", "通常攻击命中时，向命中的敌人方向显示长6m、宽0.6m的直线预警，持续0.3秒，随后以0.3秒的间隔造成2次光属性伤害。每次伤害相当于攻击力与法术强度中较高一方的8%，同一敌人最多命中2次。冷却5秒。",
                new[] { C("ErebosGaze",BossErebosBalance.ErebosGazeValue,BossErebosBalance.ErebosGazeCap) }, new BossAction(BossEvent.MainHit,BossMechanism.ShapeAttack,BossPayload.Damage,"ErebosGaze",BossShape.Line,cooldownMillis:BossErebosBalance.WeaponA0CooldownMillis,delayMillis:BossErebosBalance.WeaponA0DelayMillis,intervalMillis:BossErebosBalance.WeaponA0IntervalMillis,count:BossErebosBalance.WeaponA0Count,maxInstances:BossErebosBalance.WeaponA0MaxInstances,rangeMilli:BossErebosBalance.WeaponA0RangeMilli,widthMilli:BossErebosBalance.WeaponA0WidthMilli,element:BossElement.Light,replaceOldest:true)),
            ErebosProfile("armor", "ダメージを受けたとき、その地点を0.5秒間予告し、半径2mの範囲に攻撃力・魔力の高い方の12%の光属性ダメージを与える。さらに敵を0.2秒かけて外側へ最大0.5m押し出す。ボスと行動妨害が効かない敵は動かない。再発動まで8秒かかる。", "When you take damage, mark that location with a warning for 0.5 seconds. Deal Light damage in a 2m radius equal to 12% of whichever is higher: your Attack or Ability Power, and push enemies outward up to 0.5m over 0.2 seconds. Bosses and enemies immune to crowd control are not moved. Cooldown: 8 seconds.", "受到伤害时，在该地点显示0.5秒的预警，对半径2m范围造成相当于攻击力与法术强度中较高一方12%的光属性伤害，并在0.2秒内将敌人向外推开最多0.5m。首领和免疫控制的敌人不会被移动。冷却8秒。",
                new[] { C("ErebosLanding",BossErebosBalance.ErebosLandingValue,BossErebosBalance.ErebosLandingCap) }, ErebosCircle(BossEvent.NativeDamageTaken,"ErebosLanding",BossErebosBalance.ArmorA0RadiusMilli,BossErebosBalance.ArmorA0DelayMillis,BossErebosBalance.ArmorA0CooldownMillis)),
            ErebosProfile("charm", "自身の移動スキルが終わったとき、着地地点を0.3秒間予告し、半径2.5mの範囲に攻撃力・魔力の高い方の10%の光属性ダメージを与える。さらに最大3体の敵を0.3秒かけて外側へ最大0.6m押し出す。ボスと行動妨害が効かない敵は動かない。再発動まで6秒かかる。", "When your movement skill ends, mark your landing location with a warning for 0.3 seconds. Deal Light damage in a 2.5m radius equal to 10% of whichever is higher: your Attack or Ability Power, and push up to 3 enemies outward up to 0.6m over 0.3 seconds. Bosses and enemies immune to crowd control are not moved. Cooldown: 6 seconds.", "自身移动技能结束时，在落地地点显示0.3秒的预警，对半径2.5m范围造成相当于攻击力与法术强度中较高一方10%的光属性伤害，并在0.3秒内将最多3名敌人向外推开最多0.6m。首领和免疫控制的敌人不会被移动。冷却6秒。",
